"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[2689],{8213:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>s,metadata:()=>a,toc:()=>c});const a=JSON.parse('{"id":"manifestations/americas-warrior-partnership","title":"America\'s Warrior Partnership","description":"When veterans, their families, and caregivers encounter fragmented local support and high suicide risk, the larger veteran-serving ecosystem uses AWP to coordinate communities and connect resources.","source":"@site/docs/manifestations/americas-warrior-partnership.md","sourceDirName":"manifestations","slug":"/manifestations/americas-warrior-partnership","permalink":"/docs/manifestations/americas-warrior-partnership","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"America\'s Warrior Partnership"},"sidebar":"tutorialSidebar","previous":{"title":"All Access Life","permalink":"/docs/manifestations/all-access-life"},"next":{"title":"Angel City Sports","permalink":"/docs/manifestations/angel-city-sports"}}');var r=t(4848),i=t(8453);const s={title:"America's Warrior Partnership"},o=void 0,l={},c=[{value:"ENABLE Model location",id:"enable-model-location",level:2},{value:"What it is",id:"what-it-is",level:3},{value:"Why it matters",id:"why-it-matters",level:3},{value:"Real-world example",id:"real-world-example",level:3},{value:"What care sounds like",id:"what-care-sounds-like",level:3},{value:"What neglect sounds like",id:"what-neglect-sounds-like",level:3},{value:"What compensation sounds like",id:"what-compensation-sounds-like",level:3}];function h(e){const n={a:"a",blockquote:"blockquote",h2:"h2",h3:"h3",hr:"hr",li:"li",p:"p",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.p,{children:"When veterans, their families, and caregivers encounter fragmented local support and high suicide risk, the larger veteran-serving ecosystem uses AWP to coordinate communities and connect resources."}),"\n",(0,r.jsx)(n.h2,{id:"enable-model-location",children:"ENABLE Model location"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/post-launch/human-help",children:"Post-launch Compensations \u2192 Use Humans for Assistance"})}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"AWP operates in the post-launch phase, as a human-centred coordination network stepping in to compensate for gaps in veteran support systems."}),"\n",(0,r.jsx)(n.h3,{id:"what-it-is",children:"What it is"}),"\n",(0,r.jsxs)(n.p,{children:["AWP functions as a national nonprofit that partners with local communities to prevent veteran suicide by connecting veteran-serving organizations, coordinating care, building networks of local branches and affiliates, and offering 24/7 case management via a network call line. (",(0,r.jsx)(n.a,{href:"https://www.americaswarriorpartnership.org/",title:"America's Warrior Partnership: Veteran Non-profit",children:"AWP"}),")\nIt locates itself within the U.S. veteran-service system, intervening in the moment when existing services remain fragmented, hard to locate, or disconnected.\nThe labour burden shifts to AWP\u2019s network staff and community branches: they maintain the connection work, triage when local providers cannot meet needs, and direct veterans and families into appropriate supports."]}),"\n",(0,r.jsx)(n.h3,{id:"why-it-matters",children:"Why it matters"}),"\n",(0,r.jsxs)(n.p,{children:["Within the broader veteran-support system (including federal agencies, local nonprofits, and mental-health providers), veterans often navigate complexity, duplication, and blind\u2010spots. AWP matters because it mitigates this by actively coordinating: it reduces the burden on veterans and families to \u201cfind their way\u201d, and asks organizations to link rather than replicate services. For example, AWP\u2019s 24/7 call line + network of community branches help patch gaps where local organizations may lack capacity. (",(0,r.jsx)(n.a,{href:"https://news.va.gov/93902/veterans-get-resources-support-community-through-americas-warrior-partnership/",title:"Veterans get resources, support, community through ...",children:"VA News"}),")\nBecause veteran suicide remains high and resource fragmentation persists, the compensatory labour that AWP supplies represents a visible example of social infrastructure: human-to-human coordination bridging institutional mis-alignment.\nIn doing so, it surfaces a critique: the system places on veterans the burden of navigating supports; AWP absorbs some of that burden via human work."]}),"\n",(0,r.jsx)(n.h3,{id:"real-world-example",children:"Real-world example"}),"\n",(0,r.jsxs)(n.p,{children:["In 2021 the U.S. Department of Veterans Affairs (VA) published a piece describing how AWP\u2019s Network expanded reach of local veteran organizations by offering a 24/7 caseworker line and linking local nonprofits to vetted national partners when service gaps occurred. (",(0,r.jsx)(n.a,{href:"https://news.va.gov/93902/veterans-get-resources-support-community-through-americas-warrior-partnership/",title:"Veterans get resources, support, community through ...",children:"VA News"}),")\nFor instance, a veteran-serving nonprofit in a rural county unable to handle a particular case could contact AWP\u2019s network, and AWP would task a caseworker to refer the veteran to another affiliate across counties, thus enabling continuity of care. One local branch (for example the \u201cPanhandle Warrior Partnership\u201d) serves a defined region and uses AWP\u2019s national infrastructure to hold the referral network together. (",(0,r.jsx)(n.a,{href:"https://www.americaswarriorpartnership.org/",title:"America's Warrior Partnership: Veteran Non-profit",children:"AWP"}),")\nAWP also tracks metrics: by its own website it reports \u201ccases closed\u201d, \u201cindividuals known\u201d, \u201ccounties served\u201d. (",(0,r.jsx)(n.a,{href:"https://www.americaswarriorpartnership.org/",title:"America's Warrior Partnership: Veteran Non-profit",children:"AWP"}),")"]}),"\n",(0,r.jsx)(n.h3,{id:"what-care-sounds-like",children:"What care sounds like"}),"\n",(0,r.jsxs)(n.blockquote,{children:["\n",(0,r.jsx)(n.p,{children:"\u201cI just made a single call and the coordinator found a program that my vet-friend could join that afternoon \u2014 I didn\u2019t have to chase five offices.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cOur local branch linked up with AWP\u2019s National Network and we were able to share training and tools with smaller nonprofits in our county.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cI called 1-866-AWP-VETS on a weekend and got a live caseworker who walked me through benefits and local service options.\u201d"}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"These hypothetical scenarios reflect end-user experiences where the coordination labour of AWP alleviates the user's burden."}),"\n",(0,r.jsx)(n.h3,{id:"what-neglect-sounds-like",children:"What neglect sounds like"}),"\n",(0,r.jsxs)(n.blockquote,{children:["\n",(0,r.jsx)(n.p,{children:"\u201cI filled out three intake forms at three organizations and still didn\u2019t know who could help with housing and mental-health at the same time.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cIn our county there\u2019s a veteran-service org and a mental-health clinic, but they don\u2019t talk to each other\u2014nothing coordinated for families.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cI called the number after hours, got voicemail and then no follow up Monday morning.\u201d"}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"These hypothetical scenarios show what happens when no compensatory coordination mechanism exists, leaving individuals to navigate burden themselves."}),"\n",(0,r.jsx)(n.h3,{id:"what-compensation-sounds-like",children:"What compensation sounds like"}),"\n",(0,r.jsxs)(n.blockquote,{children:["\n",(0,r.jsx)(n.p,{children:"\u201cWe spent four hours mapping all the veteran-service agencies in our region, created a shared spreadsheet, and AWP helped us link up; otherwise the veteran would\u2019ve lost days waiting for paperwork.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cOur nonprofit took on extra staffing to serve as the hub for the AWP affiliate here \u2014 we handle referrals, data entry, follow-up calls so that clients don\u2019t fall through the cracks.\u201d"}),"\n",(0,r.jsx)(n.p,{children:"\u201cI ended up coordinating between the VA, a housing provider, and AWP\u2019s caseworker just to keep my brother from missing a treatment slot \u2014 that coordination work fell on my shoulders.\u201d"}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"These hypothetical scenarios highlight the redistributed labour: AWP and affiliated organizations (and sometimes families) pick up the coordination, follow-up, triage that the underlying system should have provided. The labour remains real, ongoing, and burdensome."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.p,{children:"All observations occur within the context of the U.S. veteran support system."})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>s,x:()=>o});var a=t(6540);const r={},i=a.createContext(r);function s(e){const n=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),a.createElement(i.Provider,{value:n},e.children)}}}]);